import math

def is_square(n):
    if n < 0:
        return False
    if n == 0:
        return True
    # Using math.isqrt for integer square root calculation
    root = math.isqrt(n)
    return root * root == n

def P(x, a2, a1, a0):
    # P(x) = x^3 + a2*x^2 + a1*x + a0
    return x**3 + a2 * x**2 + a1 * x + a0

